CustomField.formula:
IF(NOT(ISBLANK(TEXT(State_HQ__c))),
    IF(CONTAINS($Label.Subregion_AMER_Pacific_Northwest,TEXT(State_HQ__c) + ";"),"AMER - Pacific Northwest",
        IF(TEXT(State_HQ__c) = "California" || TEXT(State_HQ__c) = "CA","AMER - California",
            IF(CONTAINS($Label.Subregion_AMER_Mountain_West,TEXT(State_HQ__c) + ";"),"AMER - Mountain West",
                IF(CONTAINS($Label.Subregion_AMER_Southwest,TEXT(State_HQ__c) + ";"),"AMER - Southwest",
                    IF(CONTAINS($Label.Subregion_AMER_Midwest,TEXT(State_HQ__c) + ";"),"AMER - Midwest",
                        IF(CONTAINS($Label.Subregion_AMER_Southeast,TEXT(State_HQ__c) + ";"),"AMER - Southeast",
                            IF(CONTAINS($Label.Subregion_AMER_Mid_Atlantic,TEXT(State_HQ__c) + ";"),"AMER - Mid Atlantic",
                                IF(CONTAINS($Label.Subregion_AMER_Northeast,TEXT(State_HQ__c) + ";"),"AMER - Northeast",
                                    CASE(State_HQ__c,
                                    "NY","AMER - New York",
                                    "New York","AMER - New York",
                                    "NJ","AMER - Northeast",
                                    "New Jersey","AMER - Northeast",
                                    "PA","AMER - New York",
                                    "Pennsylvania","AMER - Northeast",
                                    "Puerto Rico","AMER - N/A",
                                    "")
                                )
                            )
                        )
                    )
                )
            )
        )
    ),
    ""
)
